package edu.campus.lostfound.web;
import edu.campus.lostfound.domain.*;import edu.campus.lostfound.repository.*;import edu.campus.lostfound.service.*;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.Size;import java.time.LocalDate;import java.util.LinkedHashMap;import java.util.Map;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import org.springframework.transaction.annotation.Transactional;
@Controller public class ReportController{
 private final ReportService service;private final ReportRepository reports;private final MatchRepository matches;private final UserRepository users;private final NotificationRepository notifications;private final ClaimService claims;public ReportController(ReportService service,ReportRepository reports,MatchRepository matches,UserRepository users,NotificationRepository notifications,ClaimService claims){this.service=service;this.reports=reports;this.matches=matches;this.users=users;this.notifications=notifications;this.claims=claims;}
 @GetMapping("/")String home(Model m){m.addAttribute("reports",service.search("",null).stream().limit(6).toList());return "index";}
 @GetMapping("/dashboard")@Transactional(readOnly=true)String dashboard(Authentication auth,Model m){Long id=users.findByEmailIgnoreCase(auth.getName()).orElseThrow().getId();var myClaims=claims.mine(auth.getName());Map<Long,ItemClaim> claimByMatch=new LinkedHashMap<>();myClaims.forEach(c->claimByMatch.putIfAbsent(c.getMatch().getId(),c));m.addAttribute("currentUserId",id);m.addAttribute("claimByMatch",claimByMatch);m.addAttribute("reports",service.mine(auth.getName()));m.addAttribute("matches",matches.findByLostReportOwnerIdOrFoundReportOwnerIdOrderByScoreDesc(id,id));m.addAttribute("notifications",notifications.findTop30ByUserIdOrderByCreatedAtDesc(id));return "dashboard";}
 @PostMapping("/matches/{id}/claim")String submitClaim(@PathVariable Long id,@Valid @ModelAttribute ClaimForm form,BindingResult errors,Authentication auth,RedirectAttributes flash){if(errors.hasErrors()){flash.addFlashAttribute("error","Please describe the proof that identifies your item (up to 2000 characters).");return "redirect:/dashboard";}try{claims.submit(id,auth.getName(),form.proofDetails());flash.addFlashAttribute("notice","Claim sent to campus administration for review.");}catch(IllegalArgumentException ex){flash.addFlashAttribute("error",ex.getMessage());}return "redirect:/dashboard";}
 @GetMapping("/reports/new")String newReport(@RequestParam(defaultValue="LOST")ReportType type,Model m){m.addAttribute("form",new ReportService.CreateReport(type,"","","","",LocalDate.now(),null));return "report-form";}
 @PostMapping("/reports")String create(@Valid @ModelAttribute("form")ReportService.CreateReport form,BindingResult errors,Authentication auth,Model model,RedirectAttributes flash){if(errors.hasErrors())return "report-form";ItemReport report=service.create(form,auth.getName());flash.addFlashAttribute("notice","Report published. Potential matches are shown in your dashboard.");return "redirect:/reports/"+report.getId();}
 @GetMapping("/reports/{id}")String detail(@PathVariable Long id,Model m){m.addAttribute("report",reports.findById(id).orElseThrow());return "report-detail";}
 @GetMapping("/search")String search(@RequestParam(defaultValue="")String q,@RequestParam(required=false)ReportType type,Model m){m.addAttribute("q",q);m.addAttribute("type",type);m.addAttribute("reports",service.search(q,type));return "search";}
 public record ClaimForm(@NotBlank @Size(max=2000)String proofDetails){}
}
